-- ====================================================================
-- WUTHERING WAVES SMART TEAM BUILDER & KNOWLEDGE SYSTEM
-- Production Schema for Version 3.7+ with Extensible Versioning & RLS
-- ====================================================================

-- 1. EXTENSIONS
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- 2. RESEARCH SOURCES
CREATE TABLE IF NOT EXISTS public.research_sources (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    name TEXT NOT NULL,\n    url TEXT NOT NULL,\n    source_type TEXT NOT NULL CHECK (source_type IN ('official', 'database', 'theorycrafting', 'community')),\n    confidence_tier TEXT NOT NULL CHECK (confidence_tier IN ('high', 'medium', 'low')),\n    notes TEXT,\n    created_at TIMESTAMPTZ DEFAULT now()\n);

-- 3. GAME VERSIONS
CREATE TABLE IF NOT EXISTS public.game_versions (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    version TEXT NOT NULL UNIQUE,\n    title TEXT NOT NULL,\n    status TEXT NOT NULL CHECK (status IN ('live', 'historical', 'upcoming', 'beta', 'leak')),\n    release_date DATE NOT NULL,\n    end_date DATE,\n    is_current BOOLEAN DEFAULT false,\n    source_url TEXT,\n    verified_at TIMESTAMPTZ DEFAULT now(),\n    created_at TIMESTAMPTZ DEFAULT now()\n);

CREATE UNIQUE INDEX IF NOT EXISTS idx_game_versions_current ON public.game_versions (is_current) WHERE is_current = true;

-- 4. CHARACTERS
CREATE TABLE IF NOT EXISTS public.characters (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    slug TEXT NOT NULL UNIQUE,\n    name TEXT NOT NULL,\n    title TEXT,\n    rarity INTEGER NOT NULL CHECK (rarity IN (4, 5)),\n    element TEXT NOT NULL CHECK (element IN ('Aero', 'Electro', 'Fusion', 'Glacio', 'Havoc', 'Spectro')),\n    weapon_type TEXT NOT NULL CHECK (weapon_type IN ('Broadblade', 'Gauntlets', 'Pistols', 'Rectifier', 'Sword')),\n    release_version_id UUID REFERENCES public.game_versions(id) ON DELETE SET NULL,\n    avatar_url TEXT,\n    icon_color TEXT DEFAULT '#3b82f6',\n    is_live BOOLEAN DEFAULT true,\n    tags TEXT[] DEFAULT '{}',\n    created_at TIMESTAMPTZ DEFAULT now()\n);

-- 5. CHARACTER ROLES
CREATE TABLE IF NOT EXISTS public.character_roles (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    character_id UUID NOT NULL REFERENCES public.characters(id) ON DELETE CASCADE,\n    role TEXT NOT NULL CHECK (role IN (\n        'main_dps', 'sub_dps', 'burst_dps', 'quickswap_dps', 'off_field_dps',\n        'support', 'healer', 'shielder', 'buffer', 'debuffer',\n        'coordinated_attack', 'concerto_enabler', 'energy_support', 'utility'\n    )),\n    is_primary BOOLEAN DEFAULT false,\n    notes TEXT,\n    UNIQUE(character_id, role)\n);

-- 6. CHARACTER SKILLS & MECHANICS
CREATE TABLE IF NOT EXISTS public.character_skills (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    character_id UUID NOT NULL REFERENCES public.characters(id) ON DELETE CASCADE,\n    skill_type TEXT NOT NULL CHECK (skill_type IN ('basic_attack', 'resonance_skill', 'forte_circuit', 'resonance_liberation', 'intro_skill', 'outro_skill')),\n    name TEXT NOT NULL,\n    description TEXT NOT NULL,\n    concerto_value NUMERIC(5,2) DEFAULT 0,\n    cooldown_seconds NUMERIC(5,2) DEFAULT 0,\n    created_at TIMESTAMPTZ DEFAULT now()\n);

-- 7. CHARACTER SYNERGIES
CREATE TABLE IF NOT EXISTS public.character_synergies (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    source_character_id UUID NOT NULL REFERENCES public.characters(id) ON DELETE CASCADE,\n    target_character_id UUID NOT NULL REFERENCES public.characters(id) ON DELETE CASCADE,\n    synergy_type TEXT NOT NULL,\n    score INTEGER NOT NULL CHECK (score BETWEEN 0 AND 100),\n    conditions TEXT,\n    explanation TEXT NOT NULL,\n    version_id UUID REFERENCES public.game_versions(id) ON DELETE SET NULL,\n    confidence TEXT DEFAULT 'high' CHECK (confidence IN ('high', 'medium', 'low')),\n    verified_at TIMESTAMPTZ DEFAULT now(),\n    UNIQUE(source_character_id, target_character_id, synergy_type)\n);

-- 8. WEAPONS
CREATE TABLE IF NOT EXISTS public.weapons (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    slug TEXT NOT NULL UNIQUE,\n    name TEXT NOT NULL,\n    type TEXT NOT NULL CHECK (type IN ('Broadblade', 'Gauntlets', 'Pistols', 'Rectifier', 'Sword')),\n    rarity INTEGER NOT NULL CHECK (rarity IN (3, 4, 5)),\n    base_atk INTEGER,\n    secondary_stat_type TEXT,\n    secondary_stat_value NUMERIC(5,2),\n    passive_name TEXT,\n    passive_desc TEXT,\n    signature_character_id UUID REFERENCES public.characters(id) ON DELETE SET NULL,\n    is_live BOOLEAN DEFAULT true,\n    created_at TIMESTAMPTZ DEFAULT now()\n);

-- 9. SONATA ECHO SETS
CREATE TABLE IF NOT EXISTS public.echo_sets (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    slug TEXT NOT NULL UNIQUE,\n    name TEXT NOT NULL,\n    element TEXT,\n    two_piece_effect TEXT NOT NULL,\n    five_piece_effect TEXT NOT NULL,\n    introduced_version_id UUID REFERENCES public.game_versions(id) ON DELETE SET NULL,\n    created_at TIMESTAMPTZ DEFAULT now()\n);

-- 10. ECHOES
CREATE TABLE IF NOT EXISTS public.echoes (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    slug TEXT NOT NULL UNIQUE,\n    name TEXT NOT NULL,\n    cost INTEGER NOT NULL CHECK (cost IN (1, 3, 4)),\n    sonata_set_id UUID REFERENCES public.echo_sets(id) ON DELETE SET NULL,\n    active_skill_name TEXT,\n    active_skill_desc TEXT,\n    is_calamity BOOLEAN DEFAULT false,\n    created_at TIMESTAMPTZ DEFAULT now()\n);

-- 11. CHARACTER ECHO RECOMMENDATIONS
CREATE TABLE IF NOT EXISTS public.character_echo_recommendations (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    character_id UUID NOT NULL REFERENCES public.characters(id) ON DELETE CASCADE,\n    preferred_set_id UUID NOT NULL REFERENCES public.echo_sets(id) ON DELETE CASCADE,\n    alternative_set_id UUID REFERENCES public.echo_sets(id) ON DELETE SET NULL,\n    main_echo_id UUID REFERENCES public.echoes(id) ON DELETE SET NULL,\n    cost_distribution TEXT DEFAULT '4-3-3-1-1',\n    main_stats TEXT,\n    substat_priority TEXT,\n    reasoning TEXT NOT NULL,\n    version_id UUID REFERENCES public.game_versions(id) ON DELETE SET NULL,\n    confidence TEXT DEFAULT 'high',\n    created_at TIMESTAMPTZ DEFAULT now()\n);

-- 12. TEAMS & COMMUNITY SHARING
CREATE TABLE IF NOT EXISTS public.teams (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    public_id TEXT NOT NULL UNIQUE,\n    name TEXT NOT NULL,\n    description TEXT,\n    objective TEXT NOT NULL,\n    score INTEGER NOT NULL,\n    score_breakdown JSONB NOT NULL DEFAULT '{}'::jsonb,\n    strengths TEXT[] DEFAULT '{}',\n    weaknesses TEXT[] DEFAULT '{}',\n    rotation_summary TEXT,\n    version_id UUID REFERENCES public.game_versions(id) ON DELETE SET NULL,\n    creator_id UUID,\n    creator_name TEXT,\n    is_public BOOLEAN DEFAULT true,\n    created_at TIMESTAMPTZ DEFAULT now()\n);

-- 13. TEAM MEMBERS
CREATE TABLE IF NOT EXISTS public.team_members (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    team_id UUID NOT NULL REFERENCES public.teams(id) ON DELETE CASCADE,\n    character_id UUID NOT NULL REFERENCES public.characters(id) ON DELETE CASCADE,\n    position INTEGER NOT NULL CHECK (position BETWEEN 1 AND 5),\n    role TEXT NOT NULL,\n    is_focus BOOLEAN DEFAULT false,\n    UNIQUE(team_id, position)\n);

-- 14. TEAM ROTATIONS
CREATE TABLE IF NOT EXISTS public.team_rotations (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    team_id UUID NOT NULL REFERENCES public.teams(id) ON DELETE CASCADE,\n    title TEXT NOT NULL,\n    rotation_type TEXT DEFAULT 'standard' CHECK (rotation_type IN ('standard', 'quickswap', 'burst')),\n    difficulty TEXT DEFAULT 'medium' CHECK (difficulty IN ('easy', 'medium', 'hard', 'advanced')),\n    cycle_duration_seconds NUMERIC(4,1) DEFAULT 20.0,\n    created_at TIMESTAMPTZ DEFAULT now()\n);

-- 15. ROTATION STEPS
CREATE TABLE IF NOT EXISTS public.rotation_steps (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    rotation_id UUID NOT NULL REFERENCES public.team_rotations(id) ON DELETE CASCADE,\n    step_order INTEGER NOT NULL,\n    character_id UUID REFERENCES public.characters(id) ON DELETE SET NULL,\n    action_type TEXT NOT NULL,\n    description TEXT NOT NULL,\n    purpose TEXT,\n    timing_seconds NUMERIC(4,1),\n    created_at TIMESTAMPTZ DEFAULT now(),\n    UNIQUE(rotation_id, step_order)\n);

-- 16. USER PROFILES
CREATE TABLE IF NOT EXISTS public.user_profiles (\n    id UUID PRIMARY KEY,\n    display_name TEXT,\n    avatar_url TEXT,\n    created_at TIMESTAMPTZ DEFAULT now(),\n    updated_at TIMESTAMPTZ DEFAULT now()\n);

-- 17. USER OWNED CHARACTERS (Roster)
CREATE TABLE IF NOT EXISTS public.user_characters (\n    user_id UUID NOT NULL,\n    character_id UUID NOT NULL REFERENCES public.characters(id) ON DELETE CASCADE,\n    owned BOOLEAN DEFAULT true,\n    level INTEGER DEFAULT 90 CHECK (level BETWEEN 1 AND 90),\n    resonance_chain INTEGER DEFAULT 0 CHECK (resonance_chain BETWEEN 0 AND 6),\n    investment_level TEXT DEFAULT 'built' CHECK (investment_level IN ('unbuilt', 'budget', 'built', 'hyperinvested')),\n    notes TEXT,\n    updated_at TIMESTAMPTZ DEFAULT now(),\n    PRIMARY KEY(user_id, character_id)\n);

-- 18. USER SAVED TEAMS
CREATE TABLE IF NOT EXISTS public.user_teams (\n    user_id UUID NOT NULL,\n    team_id UUID NOT NULL REFERENCES public.teams(id) ON DELETE CASCADE,\n    saved_at TIMESTAMPTZ DEFAULT now(),\n    PRIMARY KEY(user_id, team_id)\n);

-- RLS POLICIES
ALTER TABLE public.game_versions ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.research_sources ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.characters ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.character_roles ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.character_skills ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.character_synergies ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.weapons ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.echo_sets ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.echoes ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.character_echo_recommendations ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.teams ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.team_members ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.team_rotations ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.rotation_steps ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.user_profiles ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.user_characters ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.user_teams ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Public read game_versions\" ON public.game_versions FOR SELECT USING (true);\nCREATE POLICY \"Public read research_sources\" ON public.research_sources FOR SELECT USING (true);\nCREATE POLICY \"Public read characters\" ON public.characters FOR SELECT USING (true);\nCREATE POLICY \"Public read character_roles\" ON public.character_roles FOR SELECT USING (true);\nCREATE POLICY \"Public read character_skills\" ON public.character_skills FOR SELECT USING (true);\nCREATE POLICY \"Public read character_synergies\" ON public.character_synergies FOR SELECT USING (true);\nCREATE POLICY \"Public read weapons\" ON public.weapons FOR SELECT USING (true);\nCREATE POLICY \"Public read echo_sets\" ON public.echo_sets FOR SELECT USING (true);\nCREATE POLICY \"Public read echoes\" ON public.echoes FOR SELECT USING (true);\nCREATE POLICY \"Public read character_echo_recommendations\" ON public.character_echo_recommendations FOR SELECT USING (true);\nCREATE POLICY \"Public read teams\" ON public.teams FOR SELECT USING (is_public = true OR (auth.uid() IS NOT NULL AND creator_id = auth.uid()));\nCREATE POLICY \"Public read team_members\" ON public.team_members FOR SELECT USING (true);\nCREATE POLICY \"Public read team_rotations\" ON public.team_rotations FOR SELECT USING (true);\nCREATE POLICY \"Public read rotation_steps\" ON public.rotation_steps FOR SELECT USING (true);\n\nCREATE POLICY \"Create teams\" ON public.teams FOR INSERT WITH CHECK (\n    (auth.uid() IS NULL AND creator_id IS NULL) OR (auth.uid() IS NOT NULL AND creator_id = auth.uid())\n);\nCREATE POLICY \"Create team_members\" ON public.team_members FOR INSERT WITH CHECK (true);\nCREATE POLICY \"Create team_rotations\" ON public.team_rotations FOR INSERT WITH CHECK (true);\nCREATE POLICY \"Create rotation_steps\" ON public.rotation_steps FOR INSERT WITH CHECK (true);\n\nCREATE POLICY \"Own profile read\" ON public.user_profiles FOR SELECT USING (auth.uid() = id);\nCREATE POLICY \"Own profile update\" ON public.user_profiles FOR UPDATE USING (auth.uid() = id);\nCREATE POLICY \"Own profile insert\" ON public.user_profiles FOR INSERT WITH CHECK (auth.uid() = id);\n\nCREATE POLICY \"Own characters read\" ON public.user_characters FOR SELECT USING (auth.uid() = user_id);\nCREATE POLICY \"Own characters write\" ON public.user_characters FOR ALL USING (auth.uid() = user_id);\n\nCREATE POLICY \"Own saved teams read\" ON public.user_teams FOR SELECT USING (auth.uid() = user_id);\nCREATE POLICY \"Own saved teams write\" ON public.user_teams FOR ALL USING (auth.uid() = user_id);\n